Rules.InvariantScript:
UpdateContext(
    {
        var_visibleCntZpa1: false,
        var_visibleCntZpa2: true,
        var_selectLocal: Self.Text,
        var_obstaculo: 0
    }
)

UpdateContext(
    {
        var_visibleCntZpa1: false,
        var_visibleCntZpa2: true,
        var_selectLocal: Self.Text,
        var_obstaculo: 0
    }
)

UpdateContext(
    {
        var_visibleCntZpa1: false,
        var_visibleCntZpa2: true,
        var_selectLocal: Self.Text,
        var_obstaculo: 0
    }
)

UpdateContext(
    {
        var_visibleCntZpa1: false,
        var_visibleCntZpa2: true,
        var_selectLocal: Self.Text,
        var_obstaculo: 0
    }
)

UpdateContext(
    {
        var_visibleCntZpa1: false,
        var_visibleCntZpa2: true,
        var_selectLocal: Self.Text,
        var_obstaculo: 0
    }
)

If(
    var_obstaculo = 0 Or IsBlank(TxtZpaDescObstaculo.Text) Or IsBlank(TxtZpaLocObstaculo.Text),
    Notify(
        "Erro! selecione um obstáculo e preencha os campos de texto.",
        NotificationType.Error
    );
    UpdateContext({varBordaDefault: Color.Red}),
    Switch(
        true,
        var_obstaculo = 1,
        UpdateContext({var_obstaculoTexto: "Obras"}),
        var_obstaculo = 2,
        UpdateContext({var_obstaculoTexto: "Edificações"}),
        var_obstaculo = 3,
        UpdateContext({var_obstaculoTexto: "Árvore vegetação"}),
        var_obstaculo = 4,
        UpdateContext({var_obstaculoTexto: "Auxílio à navegação"}),
        var_obstaculo = 5,
        UpdateContext({var_obstaculoTexto: "Antenas e torres"}),
        var_obstaculo = 6,
        UpdateContext({var_obstaculoTexto: "Guindastes/Gruas"}),
        var_obstaculo = 7,
        UpdateContext({var_obstaculoTexto: "Atividades perigosas"}),
        var_obstaculo = 8,
        UpdateContext({var_obstaculoTexto: "Outros obstáculos"}),
        UpdateContext({var_obstaculoTexto: ""})
    );
    Patch(
        col_ZPASobstaculos,
        Defaults(col_ZPASobstaculos),
        {
            Item: Coalesce(
                var_selectLocal,
                "Faixa de pista"
            ),
            Subitem: var_obstaculoTexto,
            Descricao: TxtZpaDescObstaculo.Text,
            Localização: TxtZpaLocObstaculo.Text,
            Altura: Value(TxtZpaObstAltura.Text),
            Iluminação: TxtZpaObstIluminacao.Text,
            Foto: UploadedImage1.Image
        }
    );
    UpdateContext(
        {
            var_obstaculo: 0,
            varBordaDefault: RGBA(
                175,
                191,
                224,
                1
            )
        }
    );
    Reset(TxtZpaDescObstaculo);
    Reset(TxtZpaLocObstaculo);
    Reset(TxtZpaObstAltura);
    Reset(TxtZpaObstIluminacao);
    Reset(AddMediaButton2)
)
